CREATE OR REPLACE FUNCTION public.mastery_identity_evidence(p_sport text,p_date date,p_athlete uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE athlete uuid:=coalesce(p_athlete,auth.uid()); answer jsonb; health_shared boolean; BEGIN answer:=public.mastery_identity_sources(p_sport,p_date,athlete); health_shared:=athlete=auth.uid() OR public.resolve_recruiting_scope(athlete,'health'); RETURN answer || jsonb_build_object('context',(SELECT jsonb_build_object('level',a.competition_level,'position',a.position_primary,'bats',a.bats_hand,'goals',a.category_goals,'sport',a.sport_primary,'dateOfBirth',m.date_of_birth,'leagueTier',m.league_tier) FROM public.athlete_context a LEFT JOIN public.athlete_mpi_settings m ON m.user_id=a.user_id AND m.sport=p_sport WHERE a.user_id=athlete AND a.sport_primary=p_sport),'atBats',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'result',a.result,'date',g.game_date,'pitchCount',a.pitch_count,'order',coalesce(a.inning,0)*10000+coalesce(a.ab_order,0),'source',a.entry_source) ORDER BY g.game_date,g.id,a.inning,a.ab_order,a.id) FROM public.gp_at_bats a JOIN public.gp_games g ON g.id=a.game_id WHERE a.user_id=athlete AND g.user_id=athlete AND g.sport=p_sport AND g.deleted_at IS NULL AND NOT g.ignored_for_training AND g.status IN ('completed','final') AND g.game_date<p_date),'[]'::jsonb),'contactPitches',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'atBatId',p.at_bat_id,'result',p.result,'strikes',p.count_strikes,'zone',p.location->'zone','outZone',p.location->'outZone') ORDER BY g.game_date,p.created_at,p.id) FROM public.gp_pitches p JOIN public.gp_games g ON g.id=p.game_id WHERE p.user_id=athlete AND g.user_id=athlete AND g.sport=p_sport AND p.perspective='hitter' AND g.deleted_at IS NULL AND NOT g.ignored_for_training AND g.status IN ('completed','final') AND g.game_date<p_date),'[]'::jsonb),'pitcherGames',coalesce((SELECT jsonb_agg(jsonb_build_object('id',g.id,'date',g.game_date,'battersFaced',g.batters_faced,'complete',g.pitching_history_complete,'pitches',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'opportunity',p.batter_opportunity,'outcome',p.batter_result) ORDER BY p.inning,p.pitch_no,p.id) FROM public.gp_pitches p WHERE p.game_id=g.id AND p.user_id=athlete AND p.perspective='pitcher'),'[]'::jsonb)) ORDER BY g.game_date,g.id) FROM public.gp_games g WHERE g.user_id=athlete AND g.sport=p_sport AND 'P'=ANY(g.my_positions) AND g.deleted_at IS NULL AND NOT g.ignored_for_training AND g.status IN ('completed','final') AND g.game_date<p_date),'[]'::jsonb),'speedLab',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'date',s.session_date,'distances',s.distances) ORDER BY s.session_date,s.id) FROM public.speed_sessions s WHERE s.user_id=athlete AND s.sport=p_sport AND NOT s.is_break_day AND s.session_date<p_date),'[]'::jsonb),'scales',coalesce((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.effective_date DESC,s.id) FROM public.scale_reference s WHERE s.sport=p_sport AND s.effective_date<=p_date),'[]'::jsonb),'humanGrades',coalesce((SELECT jsonb_agg(jsonb_build_object('id',g.id,'date',g.graded_at,'source',g.grade_source,'evaluator',g.evaluator_id,'position',coalesce(p.position,g.position_evaluated),'defense',coalesce(p.defense_grade,g.defense_grade),'arm',coalesce(p.throwing_grade,g.throwing_grade)) ORDER BY g.graded_at DESC,g.id,p.id) FROM public.vault_scout_grades g LEFT JOIN public.vault_scout_grade_positions p ON p.grade_id=g.id WHERE g.user_id=athlete AND g.evaluator_id IS NOT NULL AND g.grade_source IN ('coach_evaluated','scout_evaluated') AND g.player_rejected IS NOT TRUE AND g.graded_at::date<p_date AND EXISTS(SELECT 1 FROM public.athlete_context a WHERE a.user_id=athlete AND a.sport_primary=p_sport)),'[]'::jsonb),'throwing',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'date',r.created_at,'position',r.position_context,'metric',r.metric,'value',r.value,'unit',r.unit,'source',r.source,'missing',r.missing_reason) ORDER BY r.created_at DESC,r.id) FROM public.throwing_reps r WHERE r.user_id=athlete AND r.created_at::date<p_date AND r.missing_reason IS NULL AND EXISTS(SELECT 1 FROM public.athlete_context a WHERE a.user_id=athlete AND a.sport_primary=p_sport)),'[]'::jsonb),'catching',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'date',r.created_at,'metric',r.metric,'value',r.value,'unit',r.unit,'source',r.source,'missing',r.missing_reason) ORDER BY r.created_at DESC,r.id) FROM public.catching_reps r WHERE r.user_id=athlete AND r.created_at::date<p_date AND r.missing_reason IS NULL AND EXISTS(SELECT 1 FROM public.athlete_context a WHERE a.user_id=athlete AND a.sport_primary=p_sport)),'[]'::jsonb),'health',CASE WHEN health_shared THEN jsonb_build_object('shared',true,'pain',coalesce((SELECT jsonb_agg(jsonb_build_object('id',q.id,'date',q.entry_date,'location',q.pain_location,'scale',q.pain_scale,'scales',q.pain_scales)) FROM public.vault_focus_quizzes q WHERE q.user_id=athlete AND q.entry_date=p_date),'[]'::jsonb),'injury',coalesce((SELECT jsonb_agg(jsonb_build_object('id',d.id,'date',d.entry_date,'active',d.injury_mode,'region',d.injury_body_region)) FROM public.athlete_daily_log d WHERE d.user_id=athlete AND d.entry_date=p_date),'[]'::jsonb),'ledger',coalesce((SELECT jsonb_agg(jsonb_build_object('entry_date',l.entry_date,'source',l.source,'throw_type',l.throw_type,'count',l.count,'status',l.status)) FROM public.arm_ledger_entries l WHERE l.user_id=athlete AND l.entry_date BETWEEN p_date-14 AND p_date),'[]'::jsonb)) ELSE jsonb_build_object('shared',false) END); END $$; REVOKE ALL ON FUNCTION public.mastery_identity_evidence(text,date,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.mastery_identity_evidence(text,date,uuid) TO authenticated,service_role; COMMENT ON FUNCTION public.mastery_identity_evidence(text,date,uuid) IS 'Extends narrow training gate; health facts require canonical health sharing. Current-primary-sport guard for account-only human/throw/catch evidence. No private analysis or inferred BF.';